local config = {
  ui_story_31000101_1_dialog_content = "Huh? You called me?",
  ui_story_31000101_2_dialog_content = "I'm still getting used to being referred to as a Snowball...",
  ui_story_31000101_3_dialog_content = "That's not a problem. You have a slightly larger brain than those paramecia, so I'm sure you'll get used to it.",
  ui_story_31000101_4_dialog_content = "Could it be that maybe, possibly, perhaps you are praising me?",
  ui_story_31000101_5_dialog_content = "Of course. You're totally different from the others.",
  ui_story_31000101_6_dialog_content = "That's why I wanted to talk with you.",
  ui_story_31000101_7_dialog_content = "Alright, I'm okay with just talking.",
  ui_story_31000101_8_dialog_content = "But you just said to tell a story... and I can't seem to think of a story of my own to tell.",
  ui_story_31000101_9_dialog_content = "Really? What a shame.",
  ui_story_31000101_10_dialog_content = "Let me tell you a story.",
  ui_story_31000101_11_dialog_content = "Huh? A story about you? I'm all ears.",
  ui_story_31000101_12_dialog_content = "Well, it's a story about truth.",
  ui_story_31000101_13_option_content = "Wait... If it's just about truth, don't bother...",
  ui_story_31000101_14_dialog_content = "Oh? So, you're not interested at all?",
  ui_story_31000101_15_dialog_content = "I'm not that smart... If you're trying to teach me about truth, you may have your work cut out for you...",
  ui_story_31000101_16_dialog_content = "Alright, alright. I understand what you're trying to say.",
  ui_story_31000101_17_dialog_content = "Let's change the subject. What do you think of tombs and their treasures?",
  ui_story_31000101_18_dialog_content = "Treasure? That's more like it!",
  ui_story_31000101_19_option_content = "I am the truth!",
  ui_story_31000101_20_dialog_content = "You?",
  ui_story_31000101_21_dialog_content = "I see... I know Lady Victoria thinks you're something special, but you aren't exactly what I would call my ideal truth.",
  ui_story_31000101_22_dialog_content = "Maybe you're not looking carefully enough.",
  ui_story_31000101_23_dialog_content = "Forget it... Let's change the subject. What do you think of tombs and their treasures?",
  ui_story_31000101_24_dialog_content = "That sounds interesting!",
  ui_story_31000101_25_dialog_content = "That's right, glittering and priceless...",
  ui_story_31000101_26_dialog_content = "Treasures hidden in ancient tombs may even be relics of ancient civilizations...",
  ui_story_31000101_27_dialog_content = "It's not just you, my little Snowball. Many people are interested in such treasures.",
  ui_story_31000101_28_dialog_content = "I met such a person, who would sneak into these tombs to steal the treasures within them.",
  ui_story_31000101_29_dialog_content = "Huh? A tomb raider?",
  ui_story_31000101_30_dialog_content = "That's right. Sneaking around with a sack of goodies, trying to creep into tombs and make a clean sweep.",
  ui_story_31000101_31_dialog_content = "When I ran into him, he was so scared he almost fainted.",
  ui_story_31000101_32_dialog_content = "For a thief, running into you is essentially like running into the police...",
  ui_story_31000101_33_dialog_content = "Did you arrest him?",
  ui_story_31000101_34_dialog_content = "Arrest him?",
  ui_story_31000101_35_dialog_content = "I didn't have time...",
  ui_story_31000101_36_dialog_content = "I just wanted him to tell me his tales for ten days and ten nights.",
  ui_story_31000101_37_option_content = "You had time to listen to his tales?",
  ui_story_31000101_38_dialog_content = "It's not like I had anything else to do in that tomb.",
  ui_story_31000101_39_dialog_content = "I wanted to know more, about the outside world, the ever-changing sky, the trees that shed their leaves, and...",
  ui_story_31000101_40_dialog_content = "The people who walk this land.",
  ui_story_31000101_41_dialog_content = "I wanted him to tell me about these things.",
  ui_story_31000101_42_option_content = "The two of you spent ten days and ten nights together in a tomb?",
  ui_story_31000101_43_dialog_content = "Yes. It wasn't long enough.",
  ui_story_31000101_44_dialog_content = "If he hadn't run out of things to say, I would've stayed for even longer.",
  ui_story_31000101_45_dialog_content = "Unfortunately, he finished all the stories he knew, and that was the end of that.",
  ui_story_31000101_46_dialog_content = "You really love listening to people tell stories, don't you Sikare Dantes?",
  ui_story_31000101_47_dialog_content = "(I suddenly feel Sikare Dantes' loneliness...)",
  ui_story_31000101_48_dialog_content = "What's wrong, my little Snowball? What's with that expression all of a sudden?",
  ui_story_31000101_49_dialog_content = "Oh, it's nothing... So, out of the stories you heard over those ten days and nights, which was your favorite?",
  ui_story_31000101_50_dialog_content = "Oh, there were so many!",
  ui_story_31000101_51_dialog_content = "One of the stories was about a time he lost his way in Northland.",
  ui_story_31000101_52_dialog_content = "He said he encountered a blizzard there.",
  ui_story_31000101_53_dialog_content = "To get out of the snow, he walked on and on against the biting wind, and finally entered a forest.",
  ui_story_31000101_54_dialog_content = "He could not see the sky for the trees, and he could not identify one direction from the other, and so he marked the ground to avoid wandering aimlessly.",
  ui_story_31000101_55_dialog_content = "But after walking for a long time... He suddenly saw a mark he had made earlier on the path in front of him.",
  ui_story_31000101_56_dialog_content = "Whoa! He started going in circles!?",
  ui_story_31000101_57_dialog_content = "No... According to him, he didn't turn a single corner, and headed straight all the while.",
  ui_story_31000101_58_dialog_content = "What's more, when he finally noticed, he discovered that there were more than just marks on the road in front of him... He found his marks to the left, right, and behind him, too.",
  ui_story_31000101_59_dialog_content = "That's... so creepy!",
  ui_story_31000101_60_dialog_content = "Very much so. When I heard this, I was even too scared to let go of the skeleton in that tomb.",
  ui_story_31000101_61_dialog_content = "Urgh... Try hugging something else next time...",
  ui_story_31000101_62_dialog_content = "But then, he suddenly saw the tree in front of him shaking, and a small figure emerged.",
  ui_story_31000101_63_dialog_content = "He thought it was an Eclipsite... But he soon discovered that it was a child.",
  ui_story_31000101_64_dialog_content = "A lovely child with a red face, and big eyes that stared straight at him.",
  ui_story_31000101_65_dialog_content = "The child asked him if he was lost.",
  ui_story_31000101_66_dialog_content = "He said yes, and a look of sympathy spread across the child's face.",
  ui_story_31000101_67_option_content = "This kid is so... suspicious!",
  ui_story_31000101_68_dialog_content = "That's what I thought!",
  ui_story_31000101_69_option_content = "Was that kid... an illusion?",
  ui_story_31000101_70_dialog_content = "That's also what I thought.",
  ui_story_31000101_71_dialog_content = "But he said that when the child heard he was lost, the child walked up to him and took his hand.",
  ui_story_31000101_72_dialog_content = "Then the child said to him, \"Come with me.\"",
  ui_story_31000101_73_dialog_content = "What!?",
  ui_story_31000101_74_dialog_content = "It's shocking, I know!",
  ui_story_31000101_75_dialog_content = "But he didn't have any other options, so he followed the child.",
  ui_story_31000101_76_dialog_content = "After walking for about half an hour, the snow-white plains appeared before them.",
  ui_story_31000101_77_dialog_content = "They made it out of the forest!",
  ui_story_31000101_78_dialog_content = "Yep!",
  ui_story_31000101_79_dialog_content = "He was very grateful and wanted to thank the child, but when he turned around, the child was nowhere to be seen.",
  ui_story_31000101_80_dialog_content = "There was just the forest behind, the snow ahead, and only him, alone in that vast, frozen land.",
  ui_story_31000101_81_dialog_content = "What a strange story!",
  ui_story_31000101_82_dialog_content = "And it really wasn't an illusion?",
  ui_story_31000101_83_dialog_content = "Whether it was or not... I wasn't sure.",
  ui_story_31000101_84_dialog_content = "I just knew that I really liked this story.",
  ui_story_31000101_85_dialog_content = "In return, I gave him something he needed.",
  ui_story_31000101_86_dialog_content = "That means...",
  ui_story_31000101_87_dialog_content = "Treasure!?",
  ui_story_31000101_88_dialog_content = "Right. Enough to keep him comfortable for the rest of his life.",
  ui_story_31000101_89_dialog_content = "No, not just to keep him comfortable. He may have now used this treasure to reach heights far greater than most people could ever dream of.",
  ui_story_31000101_90_dialog_content = "That much, huh!?",
  ui_story_31000101_91_dialog_content = "If I had known I could get such a huge reward by telling you a story, I would have told you one ages ago!",
  ui_story_31000101_92_dialog_content = "Regretting your foolishness, my little Snowball?",
  ui_story_31000101_93_dialog_content = "But you probably wouldn't want the treasure I gave him, my little Snowball.",
  ui_story_31000101_94_dialog_content = "Huh? What kind of strange treasure did you give him?",
  ui_story_31000101_95_dialog_content = "Wait, you mean, the treasure in the tomb was cursed, so...",
  ui_story_31000101_96_dialog_content = "Please, don't use that kind of simple reasoning, like common paramecia would.",
  ui_story_31000101_97_dialog_content = "I gave him a treasure beyond money, beyond time, beyond the confines of civilization itself...",
  ui_story_31000101_98_dialog_content = "I gave him the secrets of truth.",
  ui_story_31000101_99_option_content = "So, you preached to him?",
  ui_story_31000101_100_dialog_content = "The truth should be gifted to the person who deserves it. And he is deserving.",
  ui_story_31000101_101_option_content = "So, you killed him?",
  ui_story_31000101_102_dialog_content = "Death may have been a way for him to appreciate and become the truth, but he didn't need it then.",
  ui_story_31000101_103_dialog_content = "I gave him the sacred book of the True Order. Because he taught me about the world for ten days and ten nights, I taught him the truth for ten days and ten nights.",
  ui_story_31000101_104_dialog_content = "Listening to you talking about truth for ten days and ten nights... Is that guy still alive?",
  ui_story_31000101_105_dialog_content = "As I just said, he must be living well.",
  ui_story_31000101_106_dialog_content = "Not only that, after accepting the truth after ten days and ten nights, he reached an epiphany.",
  ui_story_31000101_107_dialog_content = "From then on, he became the disseminator of truth, delivering the gospel of truth to people all over Astra.",
  ui_story_31000101_108_dialog_content = "Besides, he is a very good storyteller...",
  ui_story_31000101_109_dialog_content = "Sure. After all, he told you stories for ten days and ten nights...",
  ui_story_31000101_110_dialog_content = "This is why his interpretation of the truth has been praised by so many people.",
  ui_story_31000101_111_dialog_content = "He has received great support, and has been asked to spread the truth throughout the world. Of course, he has also been provided with food and accommodation in return.",
  ui_story_31000101_112_dialog_content = "So now, he never has to worry about being comfortable again.",
  ui_story_31000101_113_dialog_content = "As a disseminator of truth, he is far beyond the level of mere mortals and paramecia.",
  ui_story_31000101_114_dialog_content = "Well, I suppose you did give him a very precious treasure...",
  ui_story_31000101_115_dialog_content = "Food, drink, and a place to sleep... There are many people who can only dream of such luxuries.",
  ui_story_31000101_116_dialog_content = "My little Snowball, do you still insist on thinking like paramecia?",
  ui_story_31000101_117_dialog_content = "Sorry, I told you I'm not so smart...",
  ui_story_31000101_118_dialog_content = "Well, you can think about this point for the time being.",
  ui_story_31000101_119_dialog_content = "Wait... What's with that sly smile of yours?",
  ui_story_31000601_1_dialog_content = "The weather's been pretty cold lately. I don't see as many people out and about, but the clinic is as busy as ever.",
  ui_story_31000601_2_dialog_content = "Every service has a huge waiting list—even the line for picking up medicine is unbelievable.",
  ui_story_31000601_3_dialog_content = "Are you, by any chance, complaining about accompanying me to the clinic?",
  ui_story_31000601_4_dialog_content = "N-Not at all! What I mean is, with all of these patients, the doctor must really have their hands full...",
  ui_story_31000601_5_dialog_content = "You really lucked out, Sikare. I hear it's easy to get sick when the seasons start to change.",
  ui_story_31000601_6_dialog_content = "Thank you for your concern, but I don't get sick quite so easily. I'm only here to pick up a prescription for <color=#FFB400>insomnia</color>.",
  ui_story_31000601_7_dialog_content = "Though I must agree, I wasn't expecting the line to be so long...",
  ui_story_31000601_8_dialog_content = "It appears we'll be here for quite some time, so if you really wish to complain, I have no objections.",
  ui_story_31000601_9_option_content = "Insomnia? What do you mean?",
  ui_story_31000601_10_dialog_content = "I'm much more worried about your health than waiting in line, Sikare.",
  ui_story_31000601_11_option_content = "I'll wait with you.",
  ui_story_31000601_12_dialog_content = "I agreed to come with you to pick up medicine, so there'll be no complaining from me.",
  ui_story_31000601_13_dialog_content = "Anyway, you mentioned a prescription for insomnia?",
  ui_story_31000601_14_dialog_content = "Have you been losing sleep over something lately?",
  ui_story_31000601_15_dialog_content = "... Heh. I suppose Lady Victoria was right to regard you with such high esteem.",
  ui_story_31000601_16_dialog_content = "To get an adequate amount of restful sleep, I require total silence, but the graves have been quite noisy lately.",
  ui_story_31000601_17_dialog_content = "You mean the Starry Crypt?",
  ui_story_31000601_18_dialog_content = "Don't tell me something has been disturbing their slumber...",
  ui_story_31000601_19_dialog_content = "Your guess could very well be true. After all, you are among the chosen of the True Order.",
  ui_story_31000601_20_dialog_content = "If so, it appears I will need to be extra vigilant lest something terrible comes to pass...",
  ui_story_31000601_21_dialog_content = "I'm begging you, Doctor! Please help me!",
  ui_story_31000601_22_dialog_content = "Just let me explain myself one more time, please!",
  ui_story_31000601_23_dialog_content = "If you don't help me, I'll have nowhere else to turn...",
  ui_story_31000601_24_dialog_content = "I'm terribly sorry, ma'am.",
  ui_story_31000601_25_dialog_content = "But the doctor already told you that there is nothing he can do. I have to ask that you seek help elsewhere.",
  ui_story_31000601_26_dialog_content = "There are still plenty of <color=#FFB400>living, breathing people</color> behind you waiting to receive treatment from the doctor.",
  ui_story_31000601_27_dialog_content = "Why don't you come with me to the lobby, and we can sit together until you calm down. Would that be okay?",
  ui_story_31000601_28_dialog_content = "Someone's causing a scene at the front of the line...",
  ui_story_31000601_29_dialog_content = "It sounds like the doctor just doesn't want to treat that lady, but something that nurse said caught my attention...",
  ui_story_31000601_30_dialog_content = "What exactly did she mean by <color=#FFB400>\"living, breathing people\"</color>?",
  ui_story_31000601_31_dialog_content = "Ah, here they come.",
  ui_story_31000601_32_dialog_content = "...",
  ui_story_31000601_33_dialog_content = "Please... someone save my son...",
  ui_story_31000601_34_dialog_content = "Here, have a seat while I get you a glass of water.",
  ui_story_31000601_35_dialog_content = "I don't want water! I want someone to save my son...",
  ui_story_31000601_36_dialog_content = "Er... Pardon me, Miss? Sorry to interrupt.",
  ui_story_31000601_37_dialog_content = "May I ask why the doctor isn't willing to help that lady? She looks awfully distressed...",
  ui_story_31000601_38_dialog_content = "Also, could you explain what you meant by \"living, breathing people\" just now?",
  ui_story_31000601_39_dialog_content = "She's been coming to the clinic early every morning for the last few days, begging the doctor to save her son.",
  ui_story_31000601_40_dialog_content = "But when the doctor asks what's wrong with her son, she says that he's already dead.",
  ui_story_31000601_41_dialog_content = "Dead...?",
  ui_story_31000601_42_dialog_content = "So she keeps asking the doctor... to save her dead son?",
  ui_story_31000601_43_dialog_content = "That certainly explains your choice of words.",
  ui_story_31000601_44_dialog_content = "I can see why the doctor says he can't help.",
  ui_story_31000601_45_dialog_content = "Furthermore, she says that her son died in a haunted house.",
  ui_story_31000601_46_dialog_content = "She wants the doctor to go to the haunted house and examine his corpse personally.",
  ui_story_31000601_47_dialog_content = "But...",
  ui_story_31000601_48_dialog_content = "There's no need to hide any details from us. Just tell us what you know.",
  ui_story_31000601_49_dialog_content = "Everyone says that the only reason that house is haunted is that her son killed his friends there!",
  ui_story_31000601_50_dialog_content = "Could it be that she wants the doctor to examine her son's corpse to prove his innocence?",
  ui_story_31000601_51_dialog_content = "I'm afraid you'll have to ask her that yourself. I only heard about this from listening to the other patients gossiping.",
  ui_story_31000601_52_dialog_content = "You would be doing our clinic a great service by helping her resolve her dilemma.",
  ui_story_31000601_53_dialog_content = "M-Me? I-I was just curious about her story, that's all! As for examining a corpse, I... I...",
  ui_story_31000601_54_dialog_content = "I'll let the doctor know that you're on the case. I'm certain he'll be very grateful for your help!",
  ui_story_31000601_55_dialog_content = "Have you ever performed an autopsy, Snowball?",
  ui_story_31000601_56_dialog_content = "N-Never...",
  ui_story_31000601_57_dialog_content = "But since we already know this much about the matter, I don't think I can sleep at night until I get to the bottom the bottom of it.",
  ui_story_31000601_58_dialog_content = "You're going to help her?",
  ui_story_31000601_59_dialog_content = "Yeah... Even though I don't have a clue where to begin or find a coroner to do an autopsy...",
  ui_story_31000601_60_dialog_content = "But if what the nurse said is true, I can't just stand by and pretend I didn't hear anything.",
  ui_story_31000601_61_dialog_content = "I'll only live to regret it if I don't help a mother find peace after losing her son.",
  ui_story_31000601_62_dialog_content = "Heh... That's the Snowball I've always known.",
  ui_story_31000601_63_dialog_content = "Excuse me, Miss?",
  ui_story_31000601_64_dialog_content = "Yes? May I help you?",
  ui_story_31000601_65_dialog_content = "I have a request for you. I need... *Whispering*",
  ui_story_31000601_66_dialog_content = "If you can get those things for me, we will be more than happy to help you with that lady's predicament.",
  ui_story_31000601_67_dialog_content = "R-Really?! Of course! Just a moment.",
  ui_story_31000601_68_dialog_content = "<color=#e8d9bb>Ten minutes later...</color>",
  ui_story_31000601_69_dialog_content = "S-Sikare?!",
  ui_story_31000601_70_dialog_content = "Thank goodness I didn't get rid of that lady doctor's uniform after she left... It fits you quite well!",
  ui_story_31000601_71_dialog_content = "This briefcase has every instrument I could ask for. Thank you for your help.",
  ui_story_31000601_72_dialog_content = "My pleasure. We're all counting on you two!",
  ui_story_31000601_73_dialog_content = "Wait... Have you been a doctor all this time, Sikare?!",
  ui_story_31000601_74_dialog_content = "Depending on how you define a doctor... yes, you could say that.",
  ui_story_31000601_75_dialog_content = "Unlike the doctor in this clinic, I specialize in treating the dead, not the living.",
  ui_story_31000601_76_dialog_content = "Listening to their words and passing them on has always been my duty.",
  ui_story_31000601_77_dialog_content = "Then means you're the perfect <color=#FFB400>doctor of the dead</color> that lady needs right now!",
  ui_story_31000601_78_dialog_content = "That's why you decided to put on that doctor's uniform and help me solve her problem, right?",
  ui_story_31000601_79_dialog_content = "Of course... Unless you have someone else in mind that is willing to go perform an autopsy in a haunted house?",
  ui_story_31000601_80_dialog_content = "Come. Let's go hear what she has to say.",
  ui_story_31000601_81_dialog_content = "Huh? But what about picking up your medicine?",
  ui_story_31000601_82_dialog_content = "Something tells me that this matter is connected to the cause of my insomnia.",
  ui_story_31000601_83_dialog_content = "Perhaps by resolving her troubles, the noise around the Crypt will also cease.",
  ui_story_31000601_84_dialog_content = "Alright, let's go talk to her.",
  ui_story_31000601_85_dialog_content = "Please help my son... He's innocent, I tell you...",
  ui_story_31000601_86_dialog_content = "He would never murder someone...",
  ui_story_31000601_87_dialog_content = "Hello, ma'am. That nurse told us about your situation.",
  ui_story_31000601_88_dialog_content = "If you don't mind, could you tell us more about what happened with your son?",
  ui_story_31000601_89_dialog_content = "I believe we might be able to help you uncover the truth.",
  ui_story_31000601_90_dialog_content = "R... Really...?",
  ui_story_31000601_91_dialog_content = "I'm sorry, but are you really a doctor? And are you truly willing to help me?",
  ui_story_31000601_92_dialog_content = "What if I told you that my son is already dead? Would you still want to help me?",
  ui_story_31000601_93_dialog_content = "Of course. It is precisely because of this reason that I am willing to lend you my assistance.",
  ui_story_31000601_94_dialog_content = "Oh, thank goodness!",
  ui_story_31000601_95_dialog_content = "Finally, someone who is willing to prove my son's innocence!",
  ui_story_31000601_96_dialog_content = "Take all of my money! All of my valuables! I'll pay whatever you ask, I swear!",
  ui_story_31000601_97_dialog_content = "I require neither your money nor your valuables. They serve me no purpose.",
  ui_story_31000601_98_dialog_content = "You're not... going to turn me away, are you?",
  ui_story_31000601_99_dialog_content = "P-Please don't misunderstand! What she means is that she doesn't need any kind of financial compensation, that's all!",
  ui_story_31000601_100_dialog_content = "We've already agreed to help you, and that's exactly what we plan to do.",
  ui_story_31000601_101_dialog_content = "Now, could you tell us more about your son and his situation, please?",
  ui_story_31000601_102_dialog_content = "And why would people come up with rumors about him like that in the first place?",
  ui_story_31000601_103_dialog_content = "Let me start at the beginning...",
  ui_story_31000601_104_dialog_content = "Three days ago, my son told me that his friends were planning to explore an abandoned house on the outskirts of town.",
  ui_story_31000601_105_dialog_content = "But because he was worried about leaving me at home by myself, he told them he couldn't go.",
  ui_story_31000601_106_dialog_content = "The next morning, when he realized that his friends hadn't come home, he became worried.",
  ui_story_31000601_107_dialog_content = "I told him not to worry about me and that he should go search for his friends.",
  ui_story_31000601_108_dialog_content = "That was the last time I saw him.",
  ui_story_31000601_109_dialog_content = "It's been three days... I'm afraid your son and his friends have long perished within the house.",
  ui_story_31000601_110_dialog_content = "I waited all night for him. By the afternoon of the next day, he still hadn't come home.",
  ui_story_31000601_111_dialog_content = "By that point, I already knew. My son valued friendship over almost anything else, you see. He would've rather died at their side than leave them behind.",
  ui_story_31000601_112_dialog_content = "But no one else sees that. Instead of wanting to find the truth, they accused him of murdering his friends and slandered his good name!",
  ui_story_31000601_113_dialog_content = "You appear to be more concerned about your son's innocence than the circumstances of his death.",
  ui_story_31000601_114_dialog_content = "Is this why you want an autopsy to be performed on him?",
  ui_story_31000601_115_dialog_content = "It'd also been just the two of us. He was the only family I had left.",
  ui_story_31000601_116_dialog_content = "You have no idea how hard it is for me to accept that he's gone.",
  ui_story_31000601_117_dialog_content = "But I'd be letting him down if I don't find out the truth and clear his name!",
  ui_story_31000601_118_dialog_content = "I know that I must have caused that doctor no small amount of grief, but I didn't know where else to turn...",
  ui_story_31000601_119_dialog_content = "I have no medical expertise, and the smell of blood makes me so woozy, I can't even go near that house...",
  ui_story_31000601_120_dialog_content = "I really want to help her, Sikare... I also want to learn the truth behind that haunted house.",
  ui_story_31000601_121_dialog_content = "What about you? Do you believe her?",
  ui_story_31000601_122_dialog_content = "I don't believe anyone. I place my trust only in <color=#FFB400>the Truth</color>.",
  ui_story_31000601_123_dialog_content = "As for the <color=#FFB400>Truth</color> hidden in this mystery... We will only find the answers we seek by consulting the spirits of the dead trapped within that haunted house.",
  ui_story_31000601_124_dialog_content = "Please tell us where to find the house.",
  ui_story_31000601_125_dialog_content = "I'm so relieved that you're willing to help.",
  ui_story_31000601_126_dialog_content = "Let me take you there right away.",
  ui_story_31000601_127_dialog_content = "Once we discover the truth, maybe I'll finally be able to bring him home...",
  ui_story_31000601_128_dialog_content = "As you wish.",
  ui_story_31000601_129_dialog_content = "Let's not waste any more time. Please lead the way!",
  ui_story_31000601_130_dialog_content = "Any closer and the smell of blood will be too overwhelming. We'll stay here and wait for you, Sikare.",
  ui_story_31000601_131_dialog_content = "Very well. I should be fine on my own.",
  ui_story_31000601_132_dialog_content = "Please describe your son's appearance to me. I'll also need to collect a blood sample if you don't object.",
  ui_story_31000601_133_dialog_content = "Rest assured, my technique is perfectly sound. I won't draw more blood than necessary, and you won't smell any of it, either.",
  ui_story_31000601_134_dialog_content = "I understand... I leave everything in your capable hands, Doctor.",
  ui_story_31000601_135_dialog_content = "<color=#e8d9bb>Twenty minutes later...</color>",
  ui_story_31000601_136_dialog_content = "How did things look in there, Sikare?",
  ui_story_31000601_137_dialog_content = "Wait... You didn't come back with anything but your medical tools? Does that mean her son wasn't in there?",
  ui_story_31000601_138_dialog_content = "Are you saying there's a chance that my son is... alive?",
  ui_story_31000601_139_dialog_content = "I'm deeply sorry, but I did in fact find your son's remains inside the house.",
  ui_story_31000601_140_dialog_content = "Because his corpse was piled in with many other bodies, its decomposition rate was abnormally rapid.",
  ui_story_31000601_141_dialog_content = "As a result, I wasn't able to retrieve his body. I'm sorry.",
  ui_story_31000601_142_dialog_content = "It's fine... I'm already beyond grateful that you were willing to help...",
  ui_story_31000601_143_dialog_content = "It's still too early to thank me. I still have more to report.",
  ui_story_31000601_144_dialog_content = "Though his body had already decayed considerably, I was able to use your blood sample to locate some of his bones.",
  ui_story_31000601_145_dialog_content = "Through those bones, I was able to hear whispers of <color=#FFB400>the Truth</color>.",
  ui_story_31000601_146_dialog_content = "<color=#e8d9bb>Three days ago...</color>",
  ui_story_31000601_147_dialog_content = "Grr... Graaah...",
  ui_story_31000601_148_dialog_content = "Graaah...!",
  ui_story_31000601_149_dialog_content = "Oh no... Are you guys all right? Tell me I'm not too late!",
  ui_story_31000601_150_dialog_content = "What are you doing here?! Get out, hurry! Save yourself!",
  ui_story_31000601_151_dialog_content = "If only I hadn't suggested exploring this place, we wouldn't be up to our necks in Eclipsites...",
  ui_story_31000601_152_dialog_content = "I don't know what you're doing here, but none of you should be paying for my mistake.",
  ui_story_31000601_153_dialog_content = "That's why I'll stay here and hold them off while the rest of you run away! It's the least I can do!",
  ui_story_31000601_154_dialog_content = "Do you really think I'm the type of guy who would leave his friends to die?",
  ui_story_31000601_155_dialog_content = "I'm already here, aren't I? I'm not going back alone, dammit!",
  ui_story_31000601_156_dialog_content = "If my mom ever found out that I didn't value the lives of my best friends...",
  ui_story_31000601_157_dialog_content = "Well, I don't think she would be too happy about that.",
  ui_story_31000601_158_dialog_content = "Heh... What the hell are we gonna do with you?",
  ui_story_31000601_159_dialog_content = "I swear I'll make it up to everyone once we get out of here.",
  ui_story_31000601_160_dialog_content = "Ha! I'll do whatever it takes to make sure you keep your word, then!",
  ui_story_31000601_161_dialog_content = "Graah!!",
  ui_story_31000601_162_dialog_content = "Greeeaauuugh!!",
  ui_story_31000601_163_dialog_content = "So the Eclipsites got them...",
  ui_story_31000601_164_dialog_content = "Indeed. After a brief search, I was able to find a number of recently-deceased bodies... I believe they were his friends.",
  ui_story_31000601_165_dialog_content = "Each of them was, without a doubt, slaughtered by Eclipsites.",
  ui_story_31000601_166_dialog_content = "This means my son was never a murderer...",
  ui_story_31000601_167_dialog_content = "Correct. Also, according to my investigation, his time of death was somewhat later than that of his friends.",
  ui_story_31000601_168_dialog_content = "Given the broken state of his remains, it appears he suffered from far more attacks than they did.",
  ui_story_31000601_169_dialog_content = "So he really held on until the very end...",
  ui_story_31000601_170_dialog_content = "I always knew my son was a good boy... He did everything he could...",
  ui_story_31000601_171_dialog_content = "If this was the choice he made; if this is what his heart told him to do... Then I can accept it.",
  ui_story_31000601_172_dialog_content = "If there is such a thing as reincarnation, I'd choose to be his mother again.",
  ui_story_31000601_173_dialog_content = "Thank you both for your help. Please allow me to properly repay you for your troubles.",
  ui_story_31000601_174_dialog_content = "I'm sure my son would want this, as well.",
  ui_story_31000601_175_dialog_content = "Just name your price, and I will do everything in my power to fulfill it.",
  ui_story_31000601_176_dialog_content = "We really don't need payment, ma'am. We were happy to—",
  ui_story_31000601_177_dialog_content = "Very well, but just know there's no going back on your word now.",
  ui_story_31000601_178_dialog_content = "S-Sikare! Didn't you say you were only interested in the truth earlier...?",
  ui_story_31000601_179_dialog_content = "No, it's quite alright; every good deed deserves a reward. Please tell me what you would like as payment.",
  ui_story_31000601_180_dialog_content = "Take this business card. I would like you to contact the person on it, and tell her the truth about what happened here.",
  ui_story_31000601_181_dialog_content = "Huh?",
  ui_story_31000601_182_dialog_content = "She is an exceptionally professional and trustworthy journalist who will make the truth known to all, not just us.",
  ui_story_31000601_183_dialog_content = "This... This is all too much... You've done so much for my son and I...",
  ui_story_31000601_184_dialog_content = "I'm not doing it for your sake. As a <color=#FFB400>doctor of the dead</color>, my work is still not finished.",
  ui_story_31000601_185_dialog_content = "To some end, conveying the voices of the dead is another way to preserve the rights of those who survive them.",
  ui_story_31000601_186_dialog_content = "It is now time to do that.",
  ui_story_31000601_187_dialog_content = "You were never the mother of a murderer and had no reason to put up with all of these baseless rumors any longer.",
  ui_story_31000601_188_dialog_content = "Sikare is absolutely right. After what you and your son have been through, you shouldn't have to be insulted like that ever again.",
  ui_story_31000601_189_dialog_content = "Besides, you said you would do everything in your power to pay what we asked, right?",
  ui_story_31000601_190_dialog_content = "Thank you... Both of you. I'll make sure to tell her everything.",
  ui_story_31000601_191_dialog_content = "Good. Now I must do one last thing for them before we leave.",
  ui_story_31000601_192_dialog_content = "Faria, hear my call... Open the gates of the Crypt, and guide these unfortunate souls to their proper resting place.",
  ui_story_31000601_193_dialog_content = "I believe I will finally have a good night's sleep tonight.",
  ui_story_31000601_194_dialog_content = "May their souls find succor in the Truth's embrace.",
  ui_story_31000602_1_dialog_content = "<color=#e8d9bb>... Gloop, gloop!</color>",
  ui_story_31000602_2_dialog_content = "Ugh... This is gross...",
  ui_story_31000602_3_dialog_content = "I can barely move... Even though it feels like I'm swimming through water, it's like I'm not even floating at all.",
  ui_story_31000602_4_dialog_content = "I'm just... sinking deeper under this black tide, getting further away from the surface each second...",
  ui_story_31000602_5_dialog_content = "And what are these creatures surrounding me? I've never seen anything like them before...",
  ui_story_31000602_6_dialog_content = "Beautiful... bizarre... eerie... Am I about to become their food?",
  ui_story_31000602_7_dialog_content = "Save... save me...",
  ui_story_31000602_8_dialog_content = "Snowball... Snowball...",
  ui_story_31000602_9_dialog_content = "Is that a voice... calling me?",
  ui_story_31000602_10_dialog_content = "I... gurgle, gurgle... I'm here... gurgle, gurgle...",
  ui_story_31000602_11_dialog_content = "Don't be afraid, I'm coming...",
  ui_story_31000602_12_dialog_content = "!",
  ui_story_31000602_13_dialog_content = "S-Sikare?",
  ui_story_31000602_14_dialog_content = "It's me.",
  ui_story_31000602_15_dialog_content = "Snowball, what are you doing here?",
  ui_story_31000602_16_dialog_content = "I... gurgle, gurgle... I...",
  ui_story_31000602_17_dialog_content = "I understand. Let's talk more once we reach the shore.",
  ui_story_31000602_18_dialog_content = "Please follow the direction I'm guiding you toward. Feel the floatation of the waves.",
  ui_story_31000602_19_dialog_content = "Gurgle, gurgle...",
  ui_story_31000602_20_dialog_content = "Don't be afraid, I'll hold your hand.",
  ui_story_31000602_21_dialog_content = "O-Okay!",
  ui_story_31000602_22_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_31000602_23_dialog_content = "We... We finally made it out!",
  ui_story_31000602_24_dialog_content = "No, I can't let you out yet.",
  ui_story_31000602_25_dialog_content = "You haven't answered my previous question.",
  ui_story_31000602_26_dialog_content = "Depending on your answer, I might just let you sink into the swamp again.",
  ui_story_31000602_27_dialog_content = "O-Okay! Please, just hear me out!",
  ui_story_31000602_28_dialog_content = "Do you need something from me, Snowball?",
  ui_story_31000602_29_dialog_content = "It's just... I've seen you locking yourself in your room on the Colossus lately.",
  ui_story_31000602_30_dialog_content = "We don't get many summer days like this... Don't you want to come along with everyone else for a trip to the beach?",
  ui_story_31000602_31_dialog_content = "Sorry, but I have no such plans.",
  ui_story_31000602_32_dialog_content = "Snowball, you should know that such things don't interest me.",
  ui_story_31000602_33_dialog_content = "Yeah, I know, but there's a special promotion at the Tir' Hotel now.",
  ui_story_31000602_34_dialog_content = "There are other Aurorians like you on the Colossus who basically never go out to have fun.",
  ui_story_31000602_35_dialog_content = "This is probably the best opportunity I'm gonna get to take you all to the beach to enjoy the sea, the sun, and the... swimwear...",
  ui_story_31000602_36_dialog_content = "So, Snowball, you wish to see me in a swimsuit, do you?",
  ui_story_31000602_37_dialog_content = "No, that's not what I meant at all!",
  ui_story_31000602_38_dialog_content = "...",
  ui_story_31000602_39_dialog_content = "Then I have nothing more to say to you. Please leave.",
  ui_story_31000602_40_dialog_content = "<color=#e8d9bb>Some time later.</color>",
  ui_story_31000602_41_dialog_content = "We've been to the beach and back, but Sikare's still all alone on the Colossus...",
  ui_story_31000602_42_dialog_content = "I should go check on her, at least to ask if she wants any souvenirs!",
  ui_story_31000602_43_dialog_content = "Huh? Why's her door open?",
  ui_story_31000602_44_dialog_content = "Excuse me... Huh? She's not here?",
  ui_story_31000602_45_dialog_content = "This is... Sikare's Black Box, Faria!",
  ui_story_31000602_46_dialog_content = "Is it really okay to leave it on the ground like this? Maybe I should pick it up for her...",
  ui_story_31000602_47_dialog_content = "<color=#e8d9bb>Click-clack! Click-clack!</color>",
  ui_story_31000602_48_dialog_content = "... Is this thing moving?",
  ui_story_31000602_49_dialog_content = "<color=#e8d9bb>Click-clack!</color>",
  ui_story_31000602_50_dialog_content = "Huh? Ahhhhhhh—",
  ui_story_31000602_51_dialog_content = "(And so, I plunged into darkness, sinking non-stop, plummeting...)",
  ui_story_31000602_52_dialog_content = "(By the time I regained consciousness, I was already mired deep in this swamp, completely unable to free myself...)",
  ui_story_31000602_53_dialog_content = "So...",
  ui_story_31000602_54_dialog_content = "Is that your explanation?",
  ui_story_31000602_55_dialog_content = "Yes... Yes, and it's all true!",
  ui_story_31000602_56_dialog_content = "I just thought you might be a bit lonely by yourself on the Colossus.",
  ui_story_31000602_57_dialog_content = "I thought maybe you'd change your mind and come out to play with everyone!",
  ui_story_31000602_58_dialog_content = "Please don't use that kind of simplistic thinking to assume my thoughts, like those blockheads would.",
  ui_story_31000602_59_dialog_content = "Do I seem like someone so fickle?",
  ui_story_31000602_60_dialog_content = "Sorry... That's not what I meant.",
  ui_story_31000602_61_dialog_content = "Did I go ahead and end up someplace I shouldn't be?",
  ui_story_31000602_62_dialog_content = "If you'd really like to know the answer to that question...",
  ui_story_31000602_63_dialog_content = "How about you join me for a tour of this place?",
  ui_story_31000602_64_dialog_content = "I see both fear and curiosity in your eyes. You must be very interested in this place, yes?",
  ui_story_31000602_65_dialog_content = "Yeah. This swamp, and the creatures and plants here...",
  ui_story_31000602_66_dialog_content = "I've never seen anything like them. Could this place be...",
  ui_story_31000602_67_dialog_content = "That's correct. This is a tomb within the Starry Crypt.",
  ui_story_31000602_68_dialog_content = "Those strange creatures you've seen are the guardians here.",
  ui_story_31000602_69_dialog_content = "When you were sinking into the swamp earlier, if they had sensed any hostility...",
  ui_story_31000602_70_dialog_content = "They would have done everything in their power to eliminate you, the intruder.",
  ui_story_31000602_71_dialog_content = "So... did I narrowly escape with my life just now?",
  ui_story_31000602_72_dialog_content = "Rest assured, they know you bear no ill intentions, and they will not make any attempts on your life.",
  ui_story_31000602_73_dialog_content = "So, Sikare, that means... they knew from the very beginning that I wasn't an intruder!",
  ui_story_31000602_74_dialog_content = "Of course, they also rely on their own judgment.",
  ui_story_31000602_75_dialog_content = "Some tomb raiders are adept at hiding their intentions, but you clearly lack such guile, Snowball.",
  ui_story_31000602_76_dialog_content = "Your curiosity is almost overflowing, drowning out any trace of hostility.",
  ui_story_31000602_77_dialog_content = "Is it that obvious?",
  ui_story_31000602_78_dialog_content = "It's not a bad thing, Snowball.",
  ui_story_31000602_79_dialog_content = "For a true explorer, these bizarre and fantastic sights are treasures in their own right.",
  ui_story_31000602_80_dialog_content = "... You're right about that.",
  ui_story_31000602_81_dialog_content = "Now I've had a chance to take a proper look around, the scenery here is truly beautiful.",
  ui_story_31000602_82_dialog_content = "A mysterious, ethereal beauty... It's so different from summertime's busy, noisy beaches.",
  ui_story_31000602_83_dialog_content = "Do you walk around here often, Sikare?",
  ui_story_31000602_84_dialog_content = "Walk? \"Patrol\" would be a more fitting verb.",
  ui_story_31000602_85_dialog_content = "Like today's patrol, which yielded a very special catch—",
  ui_story_31000602_86_dialog_content = "M-Me? So the Black Box trapped me like I was its prey?",
  ui_story_31000602_87_dialog_content = "Uh, speaking of which... Shouldn't we deal with the Black Box in your room?",
  ui_story_31000602_88_dialog_content = "Deal with it?",
  ui_story_31000602_89_dialog_content = "Yeah, after all...",
  ui_story_31000602_90_dialog_content = "I don't want to trouble you to rescue someone else!",
  ui_story_31000602_91_dialog_content = "You're worried about troubling me?",
  ui_story_31000602_92_dialog_content = "I don't believe that's what you're really thinking, Snowball...",
  ui_story_31000602_93_dialog_content = "You're worried that if your Aurorian friends rashly intrude, the results would be troublesome for you, yes?",
  ui_story_31000602_94_dialog_content = "Not being bothered by other people would be better, of course!",
  ui_story_31000602_95_dialog_content = "You don't want to be bothered?",
  ui_story_31000602_96_dialog_content = "It seems you really do like the scenery here, Snowball.",
  ui_story_31000602_97_dialog_content = "You don't want to share it with the others? It's rare to hear you demonstrate such selfishness...",
  ui_story_31000602_98_dialog_content = "That's not what I meant...",
  ui_story_31000602_99_dialog_content = "Didn't you say you prefer a peaceful life?",
  ui_story_31000602_100_dialog_content = "If the other Aurorians really come here, this place will end up no different from a beach resort.",
  ui_story_31000602_101_dialog_content = "You've considered this aspect? A rationale worthy of someone Lady Victoria regards so highly.",
  ui_story_31000602_102_dialog_content = "But let me clarify something—I have no complaints about any of our companions, I simply dislike noisy environments.",
  ui_story_31000602_103_dialog_content = "If someone were to quietly accompany me, it would be better than being alone, to some extent.",
  ui_story_31000602_104_dialog_content = "R-Really?",
  ui_story_31000602_105_dialog_content = "Actually, this is also the first time I've had a chance to appreciate how beautiful it is here in the Starry Crypt. I've never seen a place like this before!",
  ui_story_31000602_106_dialog_content = "If you don't mind, I'd like to come here more often to hang out with you!",
  ui_story_31000602_107_dialog_content = "It's just...",
  ui_story_31000602_108_dialog_content = "Any concerns, Snowball?",
  ui_story_31000602_109_dialog_content = "I wish there were a more normal way to enter this place... I don't want to find myself sinking in that swamp a second time!",
  ui_story_31000602_110_dialog_content = "Don't worry. No matter which entrance you come from, or which tomb you enter...",
  ui_story_31000602_111_dialog_content = "I will come and find you immediately.",
  ui_story_31000602_112_dialog_content = "After all, the true entrance always lies in my hands.",
  ui_story_31000602_113_dialog_content = "Oh... You've already retrieved your Black Box? When did you—",
  ui_story_31000602_114_dialog_content = "What are you thinking, Snowball?",
  ui_story_31000602_115_dialog_content = "Did you... Did you come in here after me?",
  ui_story_31000602_116_dialog_content = "Interesting. Why would you think that?",
  ui_story_31000602_117_dialog_content = "Well, you didn't have time to go back and get the Black Box, and...",
  ui_story_31000602_118_dialog_content = "You wouldn't normally change into a <color=#FFB400>swimsuit</color> during your patrol, right? So does that mean...",
  ui_story_31000602_119_dialog_content = "So, Snowball, you wish to see me in a swimsuit, do you?",
  ui_story_31000602_120_dialog_content = "No, that's not what I meant at all!",
  ui_story_31000602_121_dialog_content = "Is this because of what I said earlier?",
  ui_story_31000602_122_dialog_content = "Please don't use that kind of simplistic thinking to assume my motives, like those blockheads would.",
  ui_story_31000602_123_dialog_content = "This is just the result of my own will, or perhaps a whim.",
  ui_story_31000602_124_dialog_content = "I don't want to be seen by those blockheads, nor do I wish to be judged by them.",
  ui_story_31000602_125_dialog_content = "So I only change into my swimsuit here. Understand?",
  ui_story_31000602_126_dialog_content = "But... it really looks good on you.",
  ui_story_31000602_127_dialog_content = "Compared to those magical creatures and plants...",
  ui_story_31000602_128_dialog_content = "I'd even go so far as to say you're more beautiful.",
  ui_story_31000602_129_dialog_content = "...",
  ui_story_31000602_130_dialog_content = "When did I permit you to focus your curiosity on me?",
  ui_story_31000602_131_dialog_content = "Even without bearing hostility, if you let your guard down and violate the laws of the crypt...",
  ui_story_31000602_132_dialog_content = "You might still find yourself dragged into the abyss by these dark tendrils, becoming a permanent decoration here in the tomb.",
  ui_story_31000602_133_dialog_content = "Isn't that going a little too far?",
  ui_story_31000602_134_dialog_content = "Afraid?",
  ui_story_31000602_135_dialog_content = "A little... and really kind of concerned!",
  ui_story_31000602_136_dialog_content = "Your reaction, Snowball... is really quite cute.",
  ui_story_31000602_137_dialog_content = "Don't worry, I will protect you. <size=30>After all, the one who can free me from the crypt's shackles...</size>",
  ui_story_31000602_138_dialog_content = "What?",
  ui_story_31000602_139_dialog_content = "I said... Come closer. Closer.",
  ui_story_31000602_140_dialog_content = "For your safety, Snowball, while in the crypt, you must <color=#FFB400>always</color> stay close to me.",
  ui_story_31000602_141_dialog_content = "Understand?",
  ui_story_31000602_142_dialog_content = "Okay, I won't leave you! I promise I'll stay by your side!"
}
return config
